// Transaction envelopes and contract identifiers (wiki: data/blocks#transactions, data/records#identifiers).
import { Writer, concat, u64le } from './bytes';
import { taggedHash } from './hash';

/** Resource allowance in C/S/D/G order. */
export type Resources = [bigint, bigint, bigint, bigint];

/** Canonical deployment budget (wiki: programs#canonical-deployment); every standard contract's id follows from it. */
export const DEPLOY_BUDGET: Resources = [50_000_000n, 64n, 16_777_216n, 16_777_216n];
/** A coin's deployment: the canonical budget, with two writes more for each allocation. */
export function coinDeployBudget(allocations: number): Resources {
  return [DEPLOY_BUDGET[0], DEPLOY_BUDGET[1] + 2n * BigInt(allocations), DEPLOY_BUDGET[2], DEPLOY_BUDGET[3]];
}
/** Budgets are upper bounds: blocks fill by consumption. Nested calls each hold back a reserve. */
export const EXECUTE_BUDGET: Resources = [30_000_000n, 512n, 1_048_576n, 1_048_576n];
export const CALL_BUDGET: Resources = EXECUTE_BUDGET;
/** Unsigned coin operations, a reward claim or running a scheduled action: about 1.5 million C each, most of it the coin's code price. */
export const CLAIM_BUDGET: Resources = [2_000_000n, 64n, 65_536n, 65_536n];
/** An operation and the fee payment bound to it in one batch: room for two P-256 checks and the batch itself. */
export const BATCH_BUDGET: Resources = [100_000_000n, 1024n, 2_097_152n, 2_097_152n];

function budget(w: Writer, r: Resources) {
  for (const n of r) w.u64(n);
}

export function encodeCall(target: Uint8Array, input: Uint8Array, b: Resources): Uint8Array {
  const w = new Writer().u8(1).u8(0);
  budget(w, b);
  return w.put(target).bytes(input).finish();
}

export function encodeDeploy(code: Uint8Array, input: Uint8Array, b: Resources): Uint8Array {
  const w = new Writer().u8(1).u8(1);
  budget(w, b);
  return w.bytes(code).bytes(input).finish();
}

export function transactionId(chain: Uint8Array, tx: Uint8Array): Uint8Array {
  return taggedHash('transaction', concat(chain, tx));
}

/** ContractId of a deployment: chain, transaction id and the deployment ordinal. */
export function contractId(chain: Uint8Array, tx: Uint8Array, ordinal = 0n): Uint8Array {
  return taggedHash('contract', concat(chain, transactionId(chain, tx), u64le(ordinal)));
}

/** The id of a standard contract deployed canonically: empty input, standard budget. */
export function canonicalId(chain: Uint8Array, code: Uint8Array): Uint8Array {
  return contractId(chain, encodeDeploy(code, new Uint8Array(), DEPLOY_BUDGET));
}
